<?php
require_once '/var/www/html/wp-load.php';
$ids=get_posts(['post_type'=>'product','post_status'=>['publish','draft','pending','private'],'posts_per_page'=>-1,'fields'=>'ids']);$n=0;
foreach($ids as $id){$p=wc_get_product($id);if(!$p)continue;$source=get_post_meta($id,'_bhc_source_url',true);$state=get_post_meta($id,'_bhc_catalog_quality_state',true);if($source&&$state==='reference_verified')continue;$sku=strtoupper($p->get_sku());if(strpos($sku,'BOSCH-')!==false||strpos($sku,'LG-')!==false||strpos($sku,'SONY-')!==false||strpos($sku,'SAMSUNG-')!==false)$reason='کد خانواده یا نسخه منطقه‌ای است؛ پسوند کامل مدل باید با صفحه رسمی همان محصول تطبیق شود.';elseif(strpos($sku,'X-VISION-')!==false)$reason='منبع مستقیم همان کد مدل پیدا نشده یا کد با پسوندهای چندگانه عرضه می‌شود.';elseif(strpos($sku,'EMERSUN-')!==false)$reason='صفحه مدل دقیق و مشخصات قابل انتساب به همین کد هنوز پیدا نشده است.';else $reason='منبع مستقیم همان SKU و مشخصات کامل آن هنوز نیازمند بررسی فروشگاهی/سازنده است.';update_post_meta($id,'_bhc_release_block_reason',$reason);update_post_meta($id,'_bhc_source_audit_status','pending_exact_model_source');update_post_meta($id,'_bhc_release_blocked','yes');$n++;}echo 'CLASSIFIED|'.$n."\n";
